"use client"

import * as React from "react"
import { cn } from "@/lib/utils"
import { SlidingNumber } from "@/registry/gooseui/ui/sliding-number"

interface GitHubStarsProps {
  /**
   * GitHub repository owner
   */
  owner: string
  /**
   * GitHub repository name
   */
  repo: string
  /**
   * Additional CSS classes
   */
  className?: string
  /**
   * Show repository name
   * @default true
   */
  showRepoName?: boolean
  /**
   * Custom star count (for SSR or testing)
   */
  initialStars?: number
}

function StarIcon({ className }: { className?: string }) {
  return (
    <svg
      className={className}
      viewBox="0 0 24 24"
      fill="currentColor"
      stroke="currentColor"
      strokeWidth={2}
      strokeLinejoin="round"
      aria-hidden="true"
    >
      <path d="M11.525 2.295a.53.53 0 0 1 .95 0l2.31 4.679a2.123 2.123 0 0 0 1.595 1.16l5.166.756a.53.53 0 0 1 .294.904l-3.736 3.638a2.123 2.123 0 0 0-.611 1.878l.882 5.14a.53.53 0 0 1-.771.56l-4.618-2.428a2.122 2.122 0 0 0-1.973 0L6.396 21.01a.53.53 0 0 1-.77-.56l.881-5.139a2.122 2.122 0 0 0-.611-1.879L2.16 9.795a.53.53 0 0 1 .294-.906l5.165-.755a2.122 2.122 0 0 0 1.597-1.16z" />
    </svg>
  )
}

function GitHubStars({
  owner,
  repo,
  className,
  showRepoName = true,
  initialStars,
}: GitHubStarsProps) {
  const [stars, setStars] = React.useState<number | null>(initialStars ?? null)
  const [isLoading, setIsLoading] = React.useState(initialStars === undefined)

  React.useEffect(() => {
    if (initialStars !== undefined) return
    const controller = new AbortController()
    fetch(`https://api.github.com/repos/${owner}/${repo}`, {
      headers: { Accept: "application/vnd.github.v3+json" },
      signal: controller.signal,
    })
      .then((res) => (res.ok ? res.json() : null))
      .then((data) => setStars(data?.stargazers_count ?? null))
      .catch(() => {})
      .finally(() => {
        if (!controller.signal.aborted) setIsLoading(false)
      })
    return () => controller.abort()
  }, [owner, repo, initialStars])

  return (
    <a
      href={`https://github.com/${owner}/${repo}`}
      target="_blank"
      rel="noopener noreferrer"
      className={cn(
        "group inline-flex cursor-pointer items-center gap-2 rounded-full border bg-background px-3 py-1.5 text-sm font-medium transition-colors hover:bg-accent",
        className,
      )}
    >
      <svg
        className="size-4 text-muted-foreground transition-colors group-hover:text-foreground"
        fill="currentColor"
        viewBox="0 0 24 24"
        aria-hidden="true"
      >
        <path d="M12 .297c-6.63 0-12 5.373-12 12 0 5.303 3.438 9.8 8.205 11.385.6.113.82-.258.82-.577 0-.285-.01-1.04-.015-2.04-3.338.724-4.042-1.61-4.042-1.61C4.422 18.07 3.633 17.7 3.633 17.7c-1.087-.744.084-.729.084-.729 1.205.084 1.838 1.236 1.838 1.236 1.07 1.835 2.809 1.305 3.495.998.108-.776.417-1.305.76-1.605-2.665-.3-5.466-1.332-5.466-5.93 0-1.31.465-2.38 1.235-3.22-.135-.303-.54-1.523.105-3.176 0 0 1.005-.322 3.3 1.23.96-.267 1.98-.399 3-.405 1.02.006 2.04.138 3 .405 2.28-1.552 3.285-1.23 3.285-1.23.645 1.653.24 2.873.12 3.176.765.84 1.23 1.91 1.23 3.22 0 4.61-2.805 5.625-5.475 5.92.42.36.81 1.096.81 2.22 0 1.606-.015 2.896-.015 3.286 0 .315.21.69.825.57C20.565 22.092 24 17.592 24 12.297c0-6.627-5.373-12-12-12" />
      </svg>

      {showRepoName && (
        <span className="text-muted-foreground transition-colors group-hover:text-foreground">
          {owner}/{repo}
        </span>
      )}

      <span className="flex items-center gap-1">
        <StarIcon className="size-3.5 text-amber-400" />
        {isLoading ? (
          <span className="w-8 animate-pulse rounded bg-muted">&nbsp;</span>
        ) : stars !== null ? (
          <SlidingNumber value={stars} className="text-foreground" />
        ) : (
          <span className="text-muted-foreground">—</span>
        )}
      </span>
    </a>
  )
}

export { GitHubStars, type GitHubStarsProps }
